"""A local HTML comparison using the exact unmodified evidence PNGs."""
import html,json
from pathlib import Path
R=Path(__file__).resolve().parents[2];O=R/'Docs/ProductionFinish'
panels=[('01_intro_1920x1080','Rockos Einstieg'),('03_farm_backlog','Farm und Lagerstau'),('05_workers_spin','Worker-Karte und Rollen'),('07_industry_freeplay','Industriefluss'),('10_ui_max_scale_1366x768','Kleine Auflösung, große UI')]
def image(folder,name):return f'<a href="{folder}/{name}.png" target="_blank"><img loading="lazy" src="{folder}/{name}.png" alt="{html.escape(name)}"></a>'
body='<h1>Burning Hills — Gestaltungsstand und Gebäudeentscheidung</h1><p class="gate">Endabnahme offen. 251 Gebäude-Wrapper unverändert. Die neuen Welt-, Figuren- und UI-Assets sind integriert; Entwicklungsgebäude bleiben sichtbar, bis die ausdrückliche Gebäudeentscheidung und anschließende Einzelintegration abgeschlossen sind.</p>'
body+='<nav><a href="#approval">Vier Gebäude vergleichen</a><a href="#before">Vorher / aktuell</a><a href="#matrix">Alle Spielansichten</a><a href="VALIDATION_REPORT.md">Prüfbericht</a></nav><section id="approval"><h2>Zur konkreten Freigabe: Rathaus, Coffee-Shop T01 / T12 / T24</h2><p>Gleiche Kamera, gleicher Boden, Rocko und Leuchte als Größenvergleich. Eine positive Entscheidung gilt für die dargestellte Richtung und Vorbereitung der 251 individuellen Zustände. Sie ersetzt deren Einzel-QA nicht.</p>'
for name in ['10_sprite_review_zoom26','11_sprite_review_zoom38','12_townhall_zoom14','13_coffee_final_zoom14']:body+=image('Screenshots',name)
body+='</section><section id="before"><h2>Vorher und aktuell</h2><p>Links: gesicherte Baseline vom Beginn dieses Auftrags. Rechts: aktuelle echte Unity Game View. Bilder sind nicht retuschiert.</p>'
for name,label in panels:body+=f'<h3>{label}</h3><div class="pair"><figure><figcaption>Baseline</figcaption>{image("Baseline",name)}</figure><figure><figcaption>Aktuell</figcaption>{image("Screenshots",name)}</figure></div>'
body+='</section><section id="matrix"><h2>Aktuelle Bildmatrix</h2><p>Die automatisierte Hauptpfad-Ausführung nutzt reale Session-Aktionen und UI-Callbacks. Sie ist keine menschliche Bedienabnahme. Entwicklungshäuser in diesen Ansichten sind ein offener Release-Blocker.</p>'
for p in sorted((O/'Screenshots').glob('*.png')):
    body+=f'<details><summary>{html.escape(p.name)}</summary>{image("Screenshots",p.stem)}</details>'
body+='</section><footer><a href="BUILDING_VISUAL_APPROVAL.md">Entscheidungsumfang</a> · <a href="ART_SYSTEM.md">Gestaltungsverträge</a> · <a href="PROVENANCE_AND_LICENSES.md">Quellen und Lizenzen</a> · <a href="VISUAL_ASSET_REGISTER.csv">525 Asset- und UI-Einträge</a></footer>'
(O/'comparison.html').write_text('<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Burning Hills — Visuelle Entscheidung</title><style>body{margin:auto;padding:32px;max-width:1600px;background:#102a29;color:#f2e8cd;font:18px/1.5 system-ui}h1,h2,h3{color:#efbb65}a{color:#96d8c2}nav{display:flex;gap:24px;flex-wrap:wrap;padding:18px 0}.gate{padding:20px;border:2px solid #dfad62;background:#473c2c}section{padding:20px 0}img{display:block;width:100%;height:auto;margin:12px 0;border-radius:6px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}figure{margin:0}figcaption,summary{font-weight:600}details{padding:12px;border-bottom:1px solid #38625a}summary{cursor:pointer}footer{padding:30px 0}@media(max-width:800px){.pair{grid-template-columns:1fr}body{padding:14px}}</style>'+body+'</html>',encoding='utf-8')
assert all((O/folder/(name+'.png')).is_file() for name,_ in panels for folder in ['Screenshots','Baseline'])
print('Comparison contains exact evidence images and verified baseline links.')
